<?php
namespace App\Http\Controllers\Api\V1;
use App\Enums\TripVisibility;
use App\Models\Trip;
use App\Models\TripAccessOtp;
use App\Models\TripInvitation;
use App\Models\TripMember;
use App\Services\AuditLogger;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Facades\Mail;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
class InvitationController
{
 public function store(Request $r,Trip $trip,AuditLogger $audit){$this->assertAdmin($r,$trip);abort_if($trip->visibility!==TripVisibility::PRIVATE,422,'Invitations are only used for private trips.');$d=$r->validate(['email'=>'required|email|max:255']);$plain=Str::random(64);$inv=TripInvitation::create(['trip_id'=>$trip->id,'invited_by'=>$r->user()->id,'email'=>strtolower($d['email']),'token_hash'=>hash('sha256',$plain),'expires_at'=>now()->addDays(7)]);$url=rtrim((string)env('FRONTEND_APP_URL',config('app.url')),'/').'/#invite='.urlencode($plain);Mail::raw("You have been invited to join {$trip->name} on SplitTrip. Sign in with this email and accept the invitation: {$url}\nThis invitation expires in 7 days.",function($m)use($d,$trip){$m->to($d['email'])->subject("Invitation to {$trip->name} on SplitTrip");});$audit->record($trip,$r->user(),'invitation.sent','invitation',$inv->id,['email_domain'=>substr(strrchr($d['email'],'@')?:'',1)]);return response()->json(['message'=>'Invitation sent.','invitation_id'=>$inv->id],201);}
 public function accept(Request $r,AuditLogger $audit){$d=$r->validate(['token'=>'required|string|min:32']);$inv=TripInvitation::where('token_hash',hash('sha256',$d['token']))->whereNull('accepted_at')->whereNull('revoked_at')->where('expires_at','>',now())->firstOrFail();abort_unless(strtolower($r->user()->email)===strtolower($inv->email),403,'Sign in with the invited email address.');return DB::transaction(function()use($inv,$r,$audit){$member=TripMember::firstOrCreate(['trip_id'=>$inv->trip_id,'user_id'=>$r->user()->id],['role'=>'member','status'=>'active','joined_at'=>now()]);$inv->update(['accepted_at'=>now()]);$audit->record($inv->trip,$r->user(),'invitation.accepted','invitation',$inv->id);return response()->json(['trip_id'=>$inv->trip_id,'membership'=>$member],201);});}
 public function requestOtp(Request $r,Trip $trip){abort_if($trip->visibility!==TripVisibility::PRIVATE,422);$member=$trip->members()->where('user_id',$r->user()->id)->where('status','active')->firstOrFail();$code=(string)random_int(100000,999999);TripAccessOtp::where('trip_id',$trip->id)->where('user_id',$r->user()->id)->whereNull('consumed_at')->update(['consumed_at'=>now()]);TripAccessOtp::create(['trip_id'=>$trip->id,'user_id'=>$r->user()->id,'code_hash'=>Hash::make($code),'expires_at'=>now()->addMinutes((int)config('splittrip.otp_ttl',10))]);Mail::raw("Your SplitTrip access code is {$code}. It expires in 10 minutes. If you did not request it, ignore this email.",function($m)use($r,$trip){$m->to($r->user()->email)->subject("Your {$trip->name} access code");});return response()->json(['message'=>'A one-time code has been sent to your account email.','expires_in_seconds'=>600]);}
 public function verifyOtp(Request $r,AuditLogger $audit){$d=$r->validate(['trip_id'=>'required|integer|exists:trips,id','code'=>'required|digits:6']);$trip=Trip::findOrFail($d['trip_id']);$member=$trip->members()->where('user_id',$r->user()->id)->where('status','active')->firstOrFail();$otp=TripAccessOtp::where('trip_id',$trip->id)->where('user_id',$r->user()->id)->whereNull('consumed_at')->latest()->first();if(!$otp||$otp->expires_at->isPast()||$otp->attempts>=5){throw ValidationException::withMessages(['code'=>['The code is invalid or expired. Request a new code.']]);}$otp->increment('attempts');if(!Hash::check($d['code'],$otp->code_hash))throw ValidationException::withMessages(['code'=>['The code is incorrect.']]);$otp->update(['consumed_at'=>now()]);$member->update(['last_private_verified_at'=>now()]);$audit->record($trip,$r->user(),'private_access.verified','trip',$trip->id);return response()->json(['message'=>'Private trip access verified.','verified_until'=>now()->addMinutes(30)->toISOString()]);}
 private function assertAdmin(Request $r,Trip $trip):void{$m=$trip->members()->where('user_id',$r->user()->id)->where('status','active')->first();abort_unless($m&&in_array($m->role,['owner','admin'],true),403);if($trip->visibility===TripVisibility::PRIVATE&&(!$m->last_private_verified_at||$m->last_private_verified_at->lt(now()->subMinutes((int)config('splittrip.private_access_minutes',30)))))abort(423,'Private-trip OTP required.');}
}
